{"protocolSection":{"identificationModule":{"nctId":"NCT06827236","orgStudyIdInfo":{"id":"BNT323-03"},"secondaryIdInfos":[{"id":"2024-517979-20-00","type":"CTIS"},{"id":"1011776","type":"OTHER","domain":"IRAS number"}],"organization":{"fullName":"BioNTech SE","class":"INDUSTRY"},"briefTitle":"A Clinical Study to Find the Optimal Dose of an Investigational Treatment Called BNT323 When Used in Combination With Another Investigational Treatment, BNT327, and to Test if That Combination Treatment is Safe and Beneficial for Patients With Advanced Breast Cancer","officialTitle":"A Phase I/II, Multi-site, Open-label, Two-part Trial to Evaluate the Efficacy, Safety, and Pharmacokinetics of BNT323 in Combination With BNT327 in Participants With Advanced Breast Cancer"},"statusModule":{"statusVerifiedDate":"2026-07","overallStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2025-04-23","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2029-08","type":"ESTIMATED"},"completionDateStruct":{"date":"2029-08","type":"ESTIMATED"},"studyFirstSubmitDate":"2025-02-10","studyFirstSubmitQcDate":"2025-02-10","studyFirstPostDateStruct":{"date":"2025-02-14","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-07-20","lastUpdatePostDateStruct":{"date":"2026-07-21","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"BioNTech SE","class":"INDUSTRY"},"collaborators":[{"name":"DualityBio Inc.","class":"INDUSTRY"},{"name":"BioNTech (Shanghai) Pharmaceuticals Co., Ltd.","class":"INDUSTRY"}]},"oversightModule":{"oversightHasDmc":false,"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This is a Phase I/II, multi-site, open-label, two-part study designed to evaluate the efficacy, safety, optimized dose and contribution of components of BNT323 (also known as trastuzumab pamirtecan and DB-1303) in combination with BNT327 (also known as pumitamig and PM8002) in participants with hormone receptor-positive (HR+) or hormone receptor-negative (HR-), Human epidermal growth factor receptor (HER)2-positive, HER2-low (immunohistochemistry \[IHC\] 1+ or IHC 2+/in situ hybridization -), HER2-ultralow (IHC 0, with membrane staining) or HER2-null breast cancer (BC), or triple-negative breast cancer (TNBC).","detailedDescription":"The study consists of two parts:

* Part 1 - Dose escalation: In this part of the study, participants with histologically confirmed, chemotherapy-pretreated advanced HR+, HER2-low or HER2-ultralow BC will receive BNT323 in combination with BNT327 (BNT323 + BNT327) in a dose escalation design. This will define the recommended Phase 2 dose (RP2D) for the BNT323 + BNT327 combination therapy.
* Part 2 - Dose optimization and exploratory cohorts: This part of the study will be an expansion phase, aiming to evaluate the efficacy and safety of the optimal dose combination and providing a more robust comparison against the other treatments. It will start once the enrollment in Part 1 is completed and the sponsor in conjunction with the Safety Review Committee has assessed available Part 1 efficacy and safety data. Part 2 of the study will have four cohorts, i.e., Cohorts 1 (dose optimization cohort), and Cohorts 2, 3, and 4 (exploratory cohorts). Recruitment to Cohorts 2, 3, and 4 will begin with RP2D from Part 1 and in parallel to randomization in Cohort 1.

Randomization is planned for Cohort 1 in Part 2, i.e., participants will be randomized in 2:2:1:1 ratio into one of the four arms (Arms 1-4). No randomization is planned for any other cohort in Part 2."},"conditionsModule":{"conditions":["Locally Advanced Breast Cancer","Unresectable Breast Carcinoma","Metastatic Breast Cancer"],"keywords":["Breast Cancer (BC)","Human epidermal growth factor receptor 2 (HER2)","IHC scores 0, 1+, 2+, and 3+","Antibody drug conjugate (ADC)","Programmed Death-1 (PD-1)","Programmed Death Ligand-1 (PD-L1)","Programmed Death-1 monoclonal antibodies","Anti vascular endothelial growth factor-A (anti-VEGF-A)"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE1","PHASE2"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"SEQUENTIAL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":380,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Part1 - BNT323 + BNT327 combination therapy","type":"EXPERIMENTAL","description":"Escalating dose levels (DLs) of BNT323 and BNT327 to define RP2D. Six DLs are planned, i.e., DL0-1, DL1-1, DL2-1, DL0-0, DL1-0, DL2-0, a combination of three different DLs for BNT323 (DL0, DL1, and DL2) and two DLs for BNT327 (DL0 and DL1).","interventionNames":["Drug: BNT323","Drug: BNT327"]},{"label":"Part 2 Cohort 1 - Arm 1 - RP2D of BNT323 + BNT327","type":"EXPERIMENTAL","interventionNames":["Drug: BNT323","Drug: BNT327"]},{"label":"Part 2 Cohort 1 - Arm 2 - BNT323 + BNT327","type":"EXPERIMENTAL","interventionNames":["Drug: BNT323","Drug: BNT327"]},{"label":"Part 2 Cohort 1 - Arm 3 - BNT323 monotherapy","type":"EXPERIMENTAL","description":"BNT323 monotherapy at a fixed dose","interventionNames":["Drug: BNT323"]},{"label":"Part 2 Cohort 1 - Arm 4 - BNT327 monotherapy","type":"EXPERIMENTAL","description":"BNT327 monotherapy at a fixed dose","interventionNames":["Drug: BNT327"]},{"label":"Part 2 Cohort 2 - RP2D of BNT323 + BNT327","type":"EXPERIMEN