{"protocolSection":{"identificationModule":{"nctId":"NCT07577999","orgStudyIdInfo":{"id":"IRB-78197"},"secondaryIdInfos":[{"id":"NCI-2026-03511","type":"REGISTRY","domain":"National Cancer Institute: Clinical Trials Reporting Program"}],"organization":{"fullName":"Stanford University","class":"OTHER"},"briefTitle":"The Effects of Cannabis on Post Operative Recovery After Radical Cystectomy","officialTitle":"The Effects of Cannabis on Post Operative Recovery After Radical Cystectomy"},"statusModule":{"statusVerifiedDate":"2026-07","overallStatus":"NOT_YET_RECRUITING","startDateStruct":{"date":"2027-07","type":"ESTIMATED"},"primaryCompletionDateStruct":{"date":"2028-05","type":"ESTIMATED"},"completionDateStruct":{"date":"2028-05","type":"ESTIMATED"},"studyFirstSubmitDate":"2026-05-04","studyFirstSubmitQcDate":"2026-05-04","studyFirstPostDateStruct":{"date":"2026-05-11","type":"ACTUAL"},"lastUpdateSubmitDate":"2026-07-21","lastUpdatePostDateStruct":{"date":"2026-07-23","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Stanford University","class":"OTHER"}},"oversightModule":{"isFdaRegulatedDrug":true,"isFdaRegulatedDevice":false},"descriptionModule":{"briefSummary":"This will be an open-label, single group supportive care pilot study in which patients are given cannabinoid gummies in the perioperative setting to alleviate RC/UD symptoms and improve quality of life. The primary objective will be to evaluate the safety and tolerability of a cannabigerol supplement used perioperatively (from 14 days prior to surgery to 30 days following surgery) by patients undergoing radical cystectomy with urinary diversion (RC/UD)."},"conditionsModule":{"conditions":["Non-metastatic Bladder Cancer"],"keywords":["Cannabigerol","Hemp-Derived Cannabinoid","Health-Related Quality of Life","Supportive Care"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["EARLY_PHASE1"],"designInfo":{"allocation":"NA","interventionModel":"SINGLE_GROUP","primaryPurpose":"SUPPORTIVE_CARE","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":20,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Cannabigerol Gummies","type":"EXPERIMENTAL","description":"Participants will receive cannabigerol gummies (oral, gelatin-based chewable formulation), 25 milligrams per gummy. Dosing will begin approximately 2 weeks prior to cystectomy with urinary diversion at 12.5 milligrams (one-half gummy) three times daily after meals. Based on tolerability, the dose may be increased to 25 milligrams (one gummy) three times daily or reduced to 6.25 milligrams (one-quarter gummy) 1 to 3 times daily. Treatment will continue through the perioperative period and up to 30 days postoperatively.","interventionNames":["Drug: Cannabigerol"]}],"interventions":[{"type":"DRUG","name":"Cannabigerol","description":"Gelatin-based chewable gummies containing 25 mg of cannabigerol derived from hemp, administered for one month following a two-week lead-in dose-adjustment period.","armGroupLabels":["Cannabigerol Gummies"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Incidence of Grade ≥2 Adverse Events and Dose-Limiting Toxicities","description":"Assessment of safety and tolerability of hemp-derived cannabigerol gummies based on the incidence of Grade ≥2 adverse events (AEs) that are unresponsive to dose reduction or medical management. AEs of interest include tachycardia, xerostomia, dizziness, nausea, anxiety/depression, euphoria/impairment, fatigue, and memory impairment.

Tolerability will also be evaluated by the frequency of:

Dose reductions Treatment discontinuations Patient-reported tolerability (including taste, texture, and overall acceptability)

All AEs will be graded using standard toxicity criteria and recorded throughout the study. Dose adjustments and discontinuations will be documented and attributed to treatment.","timeFrame":"From treatment initiation through 1 month post-treatment (including 2-week lead-in period)"}],"secondaryOutcomes":[{"measure":"Change in Health-Related Quality of Life (HRQoL) - EORTC QLQ-C30","description":"Change in HRQoL as measured by the Change in Health-Related Quality of Life - European Organisation for Research and Treatment of Cancer Quality of Life Questionnaire Core 30 (EORTC QLQ-C30) total and domain scores from baseline (pre-intervention) to during and after treatment with cannabigerol following cystectomy with urinary diversion. Higher scores indicate better functioning for functional scales and worse symptoms for symptom scales, per instrument scoring guidelines.","timeFrame":"Baseline (pre-surgery), during treatment, and up to 1 month post-treatment"},{"measure":"Change in Health-Related Quality of Life - Functional Assessment of Cancer Therapy-Bladder Cystectomy","description":"Change in HRQoL as measured by the FACT-Bl-Cys questionnaire from baseline to during and after treatment. Scores will be calculated according to instrument guidelines.","timeFrame":"Baseline (prior to surgery), during treatment, and up to 1 month after treatment"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

1. 18 years of age or older
2. Non-metastatic bladder cancer scheduled to undergo radical cystectomy and urinary diversion
3. Patient is able to understand consent and is willing and able to provide written informed consent
4. Patient makes their own medical decisions
5. Lives in state of California
6. Patient is able and willing to refrain from using any non-study cannabis during the screening and treatment phases of the study
7. Females of childbearing potential to utilize an acceptable birth control method while consuming the gelatin-based chewable medication
