{"protocolSection":{"identificationModule":{"nctId":"NCT01654432","orgStudyIdInfo":{"id":"2011-0004-B"},"organization":{"fullName":"Women's College Hospital","class":"OTHER"},"briefTitle":"A Randomized Controlled Comparative Study of Ultrasound-guided Paravertebral Blocks as Part of a Multimodal Regimen for Ambulatory Breast Cancer Surgery","officialTitle":"A Randomized Controlled Comparative Study of Ultrasound-guided Paravertebral Blocks as Part of a Multimodal Regimen for Ambulatory Breast Cancer Surgery"},"statusModule":{"statusVerifiedDate":"2013-11","overallStatus":"UNKNOWN","lastKnownStatus":"ACTIVE_NOT_RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2011-07"},"primaryCompletionDateStruct":{"date":"2013-05","type":"ACTUAL"},"completionDateStruct":{"date":"2013-12","type":"ESTIMATED"},"studyFirstSubmitDate":"2012-07-27","studyFirstSubmitQcDate":"2012-07-27","studyFirstPostDateStruct":{"date":"2012-07-31","type":"ESTIMATED"},"lastUpdateSubmitDate":"2013-11-15","lastUpdatePostDateStruct":{"date":"2013-11-19","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Women's College Hospital","class":"OTHER"},"collaborators":[{"name":"Ontario Ministry of Health and Long Term Care","class":"OTHER_GOV"}]},"oversightModule":{"oversightHasDmc":false},"descriptionModule":{"briefSummary":"General anesthesia and morphine based pain medicine analgesia has been the mainstay of practice in breast cancer surgery at Women's College Hospital. There is evidence to suggest that patients have a better recovery, with less pain and nausea and vomiting when nerve blocks or freezing of nerves are given in addition to a general anesthetic. Specifically for breast cancer surgery, evidence has suggested that the use of paravertebral blocks provide patients with a better quality of recovery after surgery. The aim of this study is to examine whether patients who receive the nerve blocks using an ultrasound machine in addition to general anesthesia have a better quality of recovery than patients who receive a general anesthetic alone. The hypothesis is that patients receiving ultrasound-guided paravertebral blocks (PVB) with propofol-based general anesthesia (GA) will have a better quality of recovery than patients receiving general anesthesia-opioid-analgesia. Quality of recovery will be assessed using a modification of the QoR-27, a validated instrument to assess postoperative recovery in an ambulatory surgical population."},"conditionsModule":{"conditions":["Breast Diseases"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["NA"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","whoMasked":["PARTICIPANT","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":60,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"General anaesthesia and sham nerve block","type":"PLACEBO_COMPARATOR","description":"Breast cancer surgery under general anaesthesia"},{"label":"Paravertebral Blocks (PVB)","type":"ACTIVE_COMPARATOR","description":"Breast cancer surgery under ultrasound-guided paravertebral blocks plus general anesthesia","interventionNames":["Other: Paravertebral Blocks (PVB)"]}],"interventions":[{"type":"OTHER","name":"Paravertebral Blocks (PVB)","armGroupLabels":["Paravertebral Blocks (PVB)"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"The primary outcome measure is the quality of recovery at discharge as assessed by the QoR27","description":"The patient will be met with by the study coordinator, just before discharge to administer the Quality of Recovery Questionnaire (QoR27)","timeFrame":"Within 24 hours postoperatively"},{"measure":"The primary outcome measure is the quality of recovery post operatively, as assessed by the QoR27","description":"The patient will be contacted by the study coordinator, 2 days following their surgery to administer the Quality of Recovery Questionnaire (QoR27)","timeFrame":"on average between 24-48 hours postoperatively"},{"measure":"The primary outcome measure is the quality of recovery at discharge as assessed by the QoR27","description":"The patient will be contacted by the study coordinator, 4 days following their surgery to administer the Quality of Recovery Questionnaire (QoR27)","timeFrame":"On average 72-96 hours post operatively"},{"measure":"The primary outcome measure is the quality of recovery post operatively as assessed by the QoR27","description":"The patient will be contacted by the study coordinator, 7 days following their surgery to administer the Quality of Recovery Questionnaire (QoR27)","timeFrame":"On average 7-8 days postoperatively"}],"secondaryOutcomes":[{"measure":"Neuropathic pain","description":"DN4","timeFrame":"6 months"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

